from typing import List

def cars_left(n: int, direction: List[int], strength: List[int]) -> List[int]:
    right = []      # 还活着、向右开的车（下标）
    survivors = []  # 已确定能活下来的向左车
    for i in range(n):
        if direction[i] == 1:
            right.append(i)
            continue
        alive = True
        while right and alive:
            top = right[-1]
            if strength[top] > strength[i]:
                alive = False
            elif strength[top] < strength[i]:
                right.pop()
            else:
                right.pop()
                alive = False
        if alive:
            survivors.append(i)
    return sorted(survivors + right)

if __name__ == "__main__":
    assert cars_left(3, [1, -1, 1], [5, 3, 2]) == [0, 2]
    print(cars_left(6, [1, -1, -1, 1, -1, 1], [7, 2, 3, 5, 5, 6]))  # [0, 5]
